@include('partials.anime-script')

@once
    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const LAP = 7000;
            const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

            const showShape = (shape) => shape.setAttribute('fill-opacity', shape.dataset.opacity);

            if (!window.anime || reduceMotion) {
                document.querySelectorAll('.tutwuri-shape').forEach(showShape);
                document.querySelectorAll('.tutwuri-dot').forEach((dot) => dot.style.display = 'none');
                return;
            }

            const { animate, svg } = anime;

            document.querySelectorAll('.logo-tutwuri').forEach((logo) => {
                const tracks = logo.querySelectorAll('.tutwuri-track');
                const dots = logo.querySelectorAll('.tutwuri-dot');
                const shape = logo.querySelector('.tutwuri-shape');

                tracks.forEach((track, i) => {
                    const { translateX, translateY } = svg.createMotionPath(track);

                    animate(dots[i], {
                        translateX,
                        translateY,
                        ease: 'linear',
                        duration: LAP,
                        loop: true,
                    });
                });


                const trails = svg.createDrawable(tracks);
                animate(trails, { draw: '0 0', duration: 0 });
                tracks.forEach((track) => track.setAttribute('stroke', logo.dataset.color));

                animate(trails, {
                    draw: ['0 0', '0 1'],
                    ease: 'linear',
                    duration: LAP,
                });


                animate(shape, {
                    fillOpacity: [0, Number(shape.dataset.opacity)],
                    ease: 'outQuad',
                    duration: 1200,
                    delay: LAP,
                });
                animate(tracks, {
                    strokeOpacity: [1, 0],
                    ease: 'outQuad',
                    duration: 1200,
                    delay: LAP,
                });
            });
        });
    </script>
@endonce
